css:
/* Reset default styles */
* {
    padding: 0;
    margin: 0;
    box-sizing: border-box;
}

/* Apply Poppins font to all elements except icons */
*:not(i) {
    font-family: "Poppins", sans-serif;
}

/* Set background color of the body */
body {
    background-color: #ae9cff; /* Purple background */
}

/* Style for the main container */
.white-container {
    background-color: #ffffff; /* White background */
    width: 90vmin;
    position: absolute;
    transform: translate(-50%, -50%);
    top: 50%;
    left: 50%;
    padding: 80px 50px;
    border-radius: 10px;
    box-shadow: 0 20px 40px rgba(38, 33, 61, 0.2);
}

/* Style for the search box */
.purple-search-box {
    width: 100%;
    display: flex;
    justify-content: space-between;
}

/* Style for the input field */
.purple-search-box input {
    padding: 5px;
    width: 70%;
    border: 3px solid #ae9cff; /* Full purple border */
    outline: none;
    font-size: 16px;
}

/* Style for the search button */
.purple-search-box button {
    padding: 15px 0;
    width: 25%;
    background-color: #ae9cff; /* Purple background */
    border: none;
    outline: none;
    color: #ffffff;
    border-radius: 5px;
    cursor: pointer;
    transition: background-color 0.3s; /* Smooth hover effect */
}

/* Hover effect for the search button */
.purple-search-box button:hover {
    background-color: #9b8bff; /* Slightly lighter purple */
}

/* Style for the result box */
.purple-result-box {
    position: relative;
}

/* Style for the word heading */
.purple-result-box h3 {
    font-size: 30px;
    color: #1f194c; /* Dark color for text */
}

/* Flex layout for the word and play button */
.purple-result-box .word {
    display: flex;
    justify-content: space-between;
    margin-top: 80px;
}

/* Style for the play button */
.purple-result-box button {
    background-color: transparent;
    color: #ae9cff; /* Purple icon */
    border: none;
    outline: none;
    font-size: 18px;
    cursor: pointer;
}

/* Style for the details section (part of speech and phonetic) */
.purple-result-box .details {
    display: flex;
    gap: 10px;
    color: #b3b6d4; /* Light gray */
    margin: 5px 0 20px 0;
    font-size: 14px;
}

/* Style for the word meaning */
.word-meaning {
    color: #575a7b; /* Dark gray */
}

/* Style for the word example */
.word-example {
    color: #575a7b; /* Dark gray */
    font-style: italic;
    border-left: 5px solid #ae9cff; /* Purple border */
    padding-left: 20px;
    margin-top: 30px;
}

/* Style for the error message */
.error {
    margin-top: 80px;
    text-align: center;
}

