// API base URL for dictionary entries
const url = "https://api.dictionaryapi.dev/api/v2/entries/en/";

// Select DOM elements with updated IDs
const purpleResultBox = document.getElementById("purple-result-box");
const purpleSound = document.getElementById("purple-sound");
const purpleSearchBtn = document.getElementById("purple-search-btn");

// Add click event listener to the search button
purpleSearchBtn.addEventListener("click", () => {
    // Get the input word from the text field
    let inpWord = document.getElementById("purple-input-word").value.trim();

    // Check if input is empty
    if (!inpWord) {
        purpleResultBox.innerHTML = `<h3 class="error">Please enter a word</h3>`;
        return;
    }

    // Fetch data from the Dictionary API
    fetch(`${url}${inpWord}`)
        .then((response) => response.json())
        .then((data) => {
            console.log(data); // Log the API response for debugging

            // Extract phonetic text (use top-level phonetic or first phonetics.text)
            let phoneticText = data[0]?.phonetic || (data[0]?.phonetics?.length > 0 ? data[0].phonetics[0].text : "");

            // Find the first available audio URL from the phonetics array
            let audioUrl = "";
            if (data[0]?.phonetics) {
                for (let phonetic of data[0].phonetics) {
                    if (phonetic.audio && phonetic.audio !== "") {
                        audioUrl = phonetic.audio; // Full URL including https://
                        break;
                    }
                }
            }

            // Create play button HTML only if audio is available
            let playButtonHtml = audioUrl
                ? `<button onclick="playPurpleSound()"><i class="fas fa-volume-up"></i></button>`
                : "";

            // Use optional chaining to safely access nested properties
            const partOfSpeech = data[0]?.meanings?.[0]?.partOfSpeech || "N/A";
            const definition = data[0]?.meanings?.[0]?.definitions?.[0]?.definition || "No definition found";
            const example = data[0]?.meanings?.[0]?.definitions?.[0]?.example || "";

            // Update the result box with word details
            purpleResultBox.innerHTML = `
                <div class="word">
                    <h3>${inpWord}</h3>
                    ${playButtonHtml}
                </div>
                <div class="details">
                    <p>${partOfSpeech}</p>
                    <p>/${phoneticText}/</p>
                </div>
                <p class="word-meaning">
                    ${definition}
                </p>
                <p class="word-example">
                    ${example}
                </p>`;

            // Set the audio source if available and reset previous source
            if (audioUrl) {
                purpleSound.src = ""; // Clear previous source to avoid overlap
                purpleSound.setAttribute("src", audioUrl); // Set new source directly
            }
        })
        .catch(() => {
            // Handle case when word is not found or API fails
            purpleResultBox.innerHTML = `<h3 class="error">Couldn't Find The Word</h3>`;
        });
});

// Function to play the sound
function playPurpleSound() {
    purpleSound.play().catch((error) => {
        console.error("Audio playback failed:", error);
    });
}
